  canvas.width = 400;
  canvas.height = 100;
  document.body.appendChild(canvas);

  new Chart(canvas, {
    type: 'line',
    data: {
      labels: ['', '', '', '', ''],
      datasets: [{
        data: [20, 22, 19, 30, 18],
        borderColor: 'rgb(75, 192, 192)',
        borderWidth: 2,
        fill: false,
        pointRadius: 0,
        tension: 0.1
      }]
    },
    options: {
      responsive: false,
      plugins: {
        legend: {
          display: false
        }
      },
      scales: {
        x: {
          display: false
        },
        y: {
          display: false
        }
      }
    }
  });

  return canvas.outerHTML;
}

export const meta = {
  type: 'line',
  values: [20, 22, 19, 30, 18]
};
